use vstd::prelude::*;

verus! {

fn argmax(arr: Vec<i32>) -> (result: usize)
    requires arr.len() > 0,
    ensures 
        result < arr.len(),
        forall|i: int| 0 <= i < result ==> arr[result as int] > arr[i],
        forall|i: int| result < i < arr.len() ==> arr[result as int] >= arr[i]
{
    let mut max_idx: usize = 0;
    let mut j: usize = 1;

    while j < arr.len()
        invariant
            1 <= j <= arr.len(),
            max_idx < j,
            forall|i: int| 0 <= i < max_idx ==> arr[max_idx as int] > arr[i],
            forall|i: int| max_idx < i < j ==> arr[max_idx as int] >= arr[i],
        decreases arr.len() - j
    {
        if arr[j] > arr[max_idx] {
            max_idx = j;
        }
        j = j + 1;
    }

    max_idx
}

}
