verus! {

fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] == (a[i] & b[i])
{
    let mut result: Vec<u8> = Vec::new();
    let mut idx: usize = 0;

    while idx < a.len()
        invariant
            a.len() == b.len(),
            idx <= a.len(),
            result.len() == idx,
            forall|i: int| 0 <= i < idx ==> result[i] == (a[i] & b[i]),
        decreases a.len() - idx,
    {
        result.push(a[idx] & b[idx]);
        idx = idx + 1;
    }

    result
}

}
