    requires 
        a.len() == b.len(),
        a.len() > 0,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == a@[i] ^ b@[i],
{
    let mut result: Vec<u8> = Vec::new();
    let mut idx: usize = 0;

    while idx < a.len()
        invariant
            a.len() == b.len(),
            idx <= a.len(),
            result.len() == idx,
            forall|i: int| 0 <= i < idx as int ==> result@[i] == a@[i] ^ b@[i],
        decreases
            a.len() - idx,
    {
        result.push(a[idx] ^ b[idx]);
        idx = idx + 1;
    }

    result
