use vstd::prelude::*;

verus! {
/* Matrix type definition - represents an m×n matrix */
pub struct Matrix<T> {
    pub data: Vec<Vec<T>>,
    pub rows: usize,
    pub cols: usize,
}

impl<T: Copy> Matrix<T> {
    pub open spec fn view(self) -> Seq<Seq<T>> {
        self.data@.map(|i: int, row: Vec<T>| row@)
    }

    pub open spec fn wf(self) -> bool {
        &&& self.data.len() == self.rows
        &&& forall|i: int| 0 <= i < self.data.len() ==> self.data[i].len() == self.cols
    }

    pub open spec fn index(self, i: int, j: int) -> T 
        recommends 0 <= i < self.rows && 0 <= j < self.cols && self.wf()
    {
        self.data[i][j]
    }

    pub open spec fn size(self) -> int {
        self.rows * self.cols
    }
}

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (ret: Matrix<i8>)
    requires 
        a.len() > 0,
        shape.len() == 2,
        shape[0] > 0,
        shape[1] > 0,
        shape[0] as int == a.len() || shape[1] as int == a.len(),
    ensures
        ret.wf(),
        ret.rows == shape[0] as usize,
        ret.cols == shape[1] as usize,
        ret.size() == shape[0] as int * shape[1] as int,
        forall|i: int, j: int| 0 <= i < shape[0] as int && 0 <= j < shape[1] as int ==> {
            if shape[0] as int == a.len() {
                ret.index(i, j) == a[i as int]
            } else {
                ret.index(i, j) == a[j as int]
            }
        }
{
    let rows = shape[0] as usize;
    let cols = shape[1] as usize;
    let broadcast_rows = (shape[0] as usize) == a.len();

    let mut data: Vec<Vec<i8>> = Vec::new();
    let mut i: usize = 0;

    while i < rows
        invariant
            rows == shape[0] as usize,
            cols == shape[1] as usize,
            broadcast_rows == ((shape[0] as usize) == a.len()),
            a.len() > 0,
            shape[0] as int == a.len() || shape[1] as int == a.len(),
            0 <= i <= rows,
            data.len() == i,
            forall|k: int| 0 <= k < i as int ==> data[k].len() == cols,
            forall|k: int, l: int| 0 <= k < i as int && 0 <= l < cols as int ==> {
                if broadcast_rows {
                    data[k][l] == a[k]
                } else {
                    data[k][l] == a[l]
                }
            },
        decreases rows - i
    {
        let mut row: Vec<i8> = Vec::new();
        let mut j: usize = 0;

        while j < cols
            invariant
                rows == shape[0] as usize,
                cols == shape[1] as usize,
                broadcast_rows == ((shape[0] as usize) == a.len()),
                a.len() > 0,
                shape[0] as int == a.len() || shape[1] as int == a.len(),
                0 <= i < rows,
                0 <= j <= cols,
                row.len() == j,
                forall|l: int| 0 <= l < j as int ==> {
                    if broadcast_rows {
                        row[l] == a[i as int]
                    } else {
                        row[l] == a[l]
                    }
                },
            decreases cols - j
        {
            if broadcast_rows {
                row.push(a[i]);
            } else {
                row.push(a[j]);
            }
            j = j + 1;
        }

        data.push(row);
        i = i + 1;
    }

    Matrix {
        data,
        rows,
        cols,
    }
}

}
fn main() {}

use vstd::prelude::*;

verus! {

fn clip(a: Vec<i8>, min: i8, max: i8) -> (result: Vec<i8>)
    requires min < max,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> {
            if a@[i] < min as int {
                result@[i] == min as int
            } else if a@[i] > max as int {
                result@[i] == max as int
            } else {
                result@[i] == a@[i]
            }
        }
{
    let mut result: Vec<i8> = Vec::new();
    let mut idx: usize = 0;

    while idx < a.len()
        invariant
            idx <= a.len(),
            result.len() == idx,
            forall|i: int| 0 <= i < idx ==> {
                if a@[i] < min as int {
                    result@[i] == min as int
                } else if a@[i] > max as int {
                    result@[i] == max as int
                } else {
                    result@[i] == a@[i]
                }
            }
        decreases a.len() - idx
    {
        let val = a[idx];
        if val < min {
            result.push(min);
        } else if val > max {
            result.push(max);
        } else {
            result.push(val);
        }
        idx = idx + 1;
    }

    result
}

}
