use vstd::prelude::*;

verus! {

fn equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == (a@[i] == b@[i])
{
    let n = a.len();
    let mut result: Vec<bool> = Vec::new();
    let mut idx: usize = 0;

    while idx < n
        invariant
            n == a.len(),
            n == b.len(),
            idx <= n,
            result.len() == idx,
            forall|i: int| 0 <= i < idx as int ==> result@[i] == (a@[i] == b@[i]),
        decreases n - idx,
    {
        let eq = a[idx] == b[idx];
        result.push(eq);
        idx = idx + 1;
    }

    result
}

}
