use vstd::prelude::*;

verus! {

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> (result: Vec<bool>)
    requires 
        a.len() > 0,
        a.len() == b.len(),
        tol > 0,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> 
            result[i] == (-(tol as int) < (a[i] as int) - (b[i] as int) && (a[i] as int) - (b[i] as int) < (tol as int)),
{
    let mut result: Vec<bool> = Vec::new();
    let mut idx: usize = 0;

    while idx < a.len()
        invariant
            idx <= a.len(),
            a.len() == b.len(),
            result.len() == idx,
            tol > 0,
            forall|i: int| 0 <= i < idx ==> 
                result[i] == (-(tol as int) < (a[i] as int) - (b[i] as int) && (a[i] as int) - (b[i] as int) < (tol as int)),
        decreases a.len() - idx
    {
        let diff = (a[idx] as i32) - (b[idx] as i32);
        let tol_int = tol as i32;
        let is_close = -tol_int < diff && diff < tol_int;
        result.push(is_close);
        idx += 1;
    }

    result
}

}
