use vstd::prelude::*;

verus! {

fn max(a: Vec<i8>) -> (result: i8)
    requires a.len() > 0,
    ensures 
        exists|i: int| 0 <= i < a@.len() && result as int == a@[i],
        forall|i: int| 0 <= i < a@.len() ==> a@[i] <= result as int
{
    let mut result: i8 = a[0];
    let mut n: usize = 1;

    while n < a.len()
        invariant
            1 <= n <= a.len(),
            exists|i: int| 0 <= i < n && result as int == a@[i],
            forall|i: int| 0 <= i < n ==> a@[i] <= result as int,
        decreases a.len() - n
    {
        if a[n] > result {
            result = a[n];
        }
        n = n + 1;
    }

    result
}

}
