    while idx < a.len()
        invariant
            1 <= idx <= a.len(),
            exists|i: int| 0 <= i < idx && result as int == a@[i],
            forall|i: int| 0 <= i < idx ==> result as int <= a@[i],
        decreases a.len() - idx,
    {
