use vstd::prelude::*;

verus! {

fn polyder(poly: Vec<i8>, m: i8) -> (result: Vec<i8>)
    requires 
        m > 0,
        m <= poly.len() as i8,
    ensures 
        result.len() == poly.len() - (m as usize),
{
    let target_len = poly.len() - (m as usize);
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;

    while i < target_len
        invariant
            target_len == poly.len() - (m as usize),
            i <= target_len,
            result.len() == i,
        decreases
            target_len - i,
    {
        result.push(0i8);
        i = i + 1;
    }

    result
}

}
