use vstd::prelude::*;

verus! {

fn sign(a: Vec<i32>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> {
            (a[i] > 0 ==> result[i] == 1) &&
            (a[i] == 0 ==> result[i] == 0) &&
            (a[i] < 0 ==> result[i] == -1)
        }
{
    let mut result: Vec<i32> = Vec::new();
    let mut idx: usize = 0;

    while idx < a.len()
        invariant
            idx <= a.len(),
            result.len() == idx,
            forall|i: int| 0 <= i < idx ==> {
                (a[i] > 0 ==> result[i] == 1) &&
                (a[i] == 0 ==> result[i] == 0) &&
                (a[i] < 0 ==> result[i] == -1)
            }
        decreases
            a.len() - idx
    {
        let val = a[idx];
        if val > 0 {
            result.push(1);
        } else if val == 0 {
            result.push(0);
        } else {
            result.push(-1);
        }
        idx = idx + 1;
    }

    result
}

}
fn main() {}
